import { boot } from "./remote-shared";

// 被 host 通过 Module Federation 消费的暴露模块；自身也含动态 import。
export const mount = (el) => {
  boot("remote-app mounted");
  if (el) el.textContent = "remote-app live";

  // remote 侧懒加载
  import(/* webpackChunkName: "remote-gadget-a" */ "./remote-gadget-a.js").then((m) => m.ga());

  // remote 侧表达式 import 两目录
  window.loadRemoteTemplate = (name) => import(`./remote-templates/${name}.js`);
  window.loadRemoteWidget = (name) => import(`./remote-widgets/${name}.js`);
};
